        billingarray1.push({ text: dollar1 + ' ' + checkUndefinedVal(DepositAmount1) + '\n' + dollar2 + ' ' + DepositAmount2 + '\n' + dollar3 + ' ' + DepositAmount3, fontSize: cFont, alignment: 'right' });
