    function getNewOpticalInstruction(localArray) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (localArray === undefined || localArray.length === 0)
            return;
        var cFont = 8;
        var hFont = 9;

        var bodyItem = [
            [{
                text: 'Terms & Conditions :',
                fillColor: '#eaeaea',
                bold: true,
                margin: [0, 5, 0, 5],
                fontSize: 10
            }]
        ];

        var headingFlag = 0;
        var invItem1 = [{
            type: 'square',
            ul: [],
            fontSize: 8

        }];
        var localarr = "";
        localarr = JSON.parse(localArray.OrganizationInstructions);
        angular.forEach(localarr, function (item) {
            if (item.OrgInstructions !== '') {
                invItem1[0].ul.push({
                    text: [{ text: ' ' + item.OrgInstructions, fontSize: 8 }], margin: [0, 0, 0, 5]
                });
            }
        });
        if (invItem1[0].ul.length > 0) {
            bodyItem.push(invItem1);
        }
        if (bodyItem.length === 1)
            return null;
        return bodyItem;
    }


    function getOpticalGlassLensTable(obj, type) {
        var cBold = false;
        var cFont = defaultFontSize;
        if (contentSetting.patientLabTest) {
            cBold = contentSetting.patientLabTest.isBold === "Y";
            cFont = contentSetting.patientLabTest.fontSize;
        }
        var hFont = 10;
        var cFont = 9;
        var headingFlag = 0;
        var bodyItem = [];
        var sitem = "";
        var citem = "";
        var invItem1 = [];
        var invItem2 = [];

        var bitem = [];
        angular.forEach(obj, function (mitem) {
            if (mitem.VisionData !== undefined) {
                bitem = JSON.parse(mitem.VisionData);
            }
        });

        angular.forEach(bitem.LensType, function (itm) {
            if (itm.IsActive === true) {
                invItem1.push(itm.Name);
                sitem = invItem1.join(", ");
            }
        });


        angular.forEach(bitem.LensCoating, function (itm) {
            if (itm.IsActive === true) {
                invItem2.push(itm.Name);
                citem = invItem2.join(", ");
            }
        });

        var ltype = "";
        var ctype = "";
        if (type === 'New') {
            ltype = 'LensType : ';
            ctype = 'LensCoating : ';
        }

        var patientdocDetailsArray2 = [];

        if (sitem !== "") {
            patientdocDetailsArray2.push({
                text: [{ text: ltype, fontSize: cFont, bold: true }, { text: ' ' + sitem, fontSize: cFont, bold: false }], margin: [5, 0, 2, 0], alignment: 'left', fontSize: cFont
            });
        }

        if (citem !== "") {
            patientdocDetailsArray2.push({
                text: [{ text: ctype, fontSize: cFont, bold: true }, { text: ' ' + citem, fontSize: cFont, bold: false }], margin: [0, 0, 0, 0], alignment: 'right', fontSize: cFont
            });
        }

        if (sitem !== "" || citem !== "") {
            bodyItem.push(patientdocDetailsArray2);
        }
        if (bodyItem.length === 0) {
            return null;
        }


        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                widths: [150, 200],
                heights: 5,
                body: bodyItem
            },
            layout: 'noBorders'
        };
        return patientLabTestTable;
    }



