    function getGlassLensTable(obj, type) {
        var cBold = false;
        var cFont = defaultFontSize;
        if (contentSetting.patientLabTest) {
            cBold = contentSetting.patientLabTest.isBold === "Y";
            cFont = contentSetting.patientLabTest.fontSize;
        }
        var hFont = 10;
        var cFont = 9;
        var headingFlag = 0;
        var bodyItem = [];
        var sitem = "";
        var citem = "";
        var invItem1 = [];
        var invItem2 = [];
        angular.forEach(obj, function (item) {
            angular.forEach(item.LensType, function (itm) {
                if (itm.IsActive === true) {
                    invItem1.push(itm.Name);
                    sitem = invItem1.join(", ");
                }
            });
        });
        angular.forEach(obj, function (item) {
            angular.forEach(item.LensCoating, function (itm) {
                if (itm.IsActive === true) {
                    invItem2.push(itm.Name);
                    citem = invItem2.join(", ");
                }
            });
        });

        var ltype = "";
        var ctype = "";
        if (type === 'New') {
            ltype = 'New Glass LensType : ';
            ctype = 'New Glass LensCoating : ';
        }
        if (type === 'Old') {
            ltype = 'Old Glass LensType : ';
            ctype = 'Old Glass LensCoating : ';
        }

        var patientdocDetailsArray1 = [];
        var patientdocDetailsArray2 = [];

        if (sitem !== "") {
            patientdocDetailsArray1.push({
                text: [{ text: ltype, fontSize: cFont, bold: true }, { text: ' ' + sitem, fontSize: cFont, bold: false }], fontSize: cFont
            });
        }

        if (citem !== "") {
            patientdocDetailsArray2.push({
                text: [{ text: ctype, fontSize: cFont, bold: true }, { text: ' ' + citem, fontSize: cFont, bold: false }], fontSize: cFont
            });
        }

        if (sitem !== "") {
            bodyItem.push(patientdocDetailsArray1);
        }
        if (citem !== "") {
            bodyItem.push(patientdocDetailsArray2);
        }
        if (bodyItem.length === 0) {
            return null;
        }


        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                //widths: [300, '*'],
                widths: ['*'],
                //heights: 5,
                body: bodyItem
            },
            layout: 'noBorders'
        };
        return patientLabTestTable;
    }


