    function getNewDesignGonioscopyInvRows(cacheStorageItem) {
        var cBold = true;
        if (cacheStorageItem.length === 0)
            return;
        var cFont = 7;
        var hFont = 8;
        var bodyItem = [];
        cacheStorageItem[0].LeftEye = cacheStorageItem[0].LeftEye || "";
        cacheStorageItem[0].RightEye = cacheStorageItem[0].RightEye || "";
        cacheStorageItem[0].LeftEyeFreq = cacheStorageItem[0].LeftEyeFreq || 0;
        cacheStorageItem[0].RightEyeFreq = cacheStorageItem[0].RightEyeFreq || 0;
        cacheStorageItem[0].RightEyeRemarks = cacheStorageItem[0].RightEyeRemarks || "";
        cacheStorageItem[0].LeftEyeRemarks = cacheStorageItem[0].LeftEyeRemarks || "";
        if (cacheStorageItem[0].RightEyeCdRatio !== '' || cacheStorageItem[0].LeftEyeCdRatio !== '' || cacheStorageItem[0].RightEyeArray.length !== 0 || cacheStorageItem[0].LeftEyeArray.length !== 0 || cacheStorageItem[0].LeftEye !== '' || cacheStorageItem[0].RightEye !== '' || cacheStorageItem[0].LeftEyeFreq !== 0 || cacheStorageItem[0].RightEyeFreq !== 0 || cacheStorageItem[0].RightEyeRemarks !== '' || cacheStorageItem[0].LeftEyeRemarks != '') {
            bodyItem = [
                [{
                    text: 'Gonioscopy',
                    alignment: 'center',
                    fillColor: '#d3d3d8',
                    bold: cBold,
                    margin: [0, 5, 0, 5],
                    fontSize: hFont
                },
                {
                    text: 'Right Eye(OD)',
                    alignment: 'center',
                    fillColor: '#d3d3d8',
                    bold: cBold,
                    margin: [0, 5, 0, 5],
                    fontSize: hFont
                },
                { text: 'Left Eye(OS)', alignment: 'center', fillColor: '#d3d3d8', bold: cBold, margin: [0, 5, 0, 5], fontSize: hFont }
                ]
            ];

            var strPosteriorREye = "";
            var strPosteriorLEye = "";
            angular.forEach(cacheStorageItem, function (intem) {
                var strPosteriorREye = "";
                var strPosteriorLEye = "";
                var invItem = [];

                invItem.push({
                    text: intem.InvestigationDesc,
                    color: 'black',
                    fontSize: cFont,
                    bold: cBold
                });

                if (intem.RightEyeCdRatio !== '') {
                    strPosteriorREye += 'CD Ratio : ' + intem.RightEyeCdRatio + '\n';
                }
                if (intem.RightEyeFreq !== '' && intem.RightEyeFreq !== 0) {
                    strPosteriorREye += 'Frequency : ' + (intem.RightEyeFreq === 'positive' ? 'FR+' : 'FR-') + '\n';
                }
                if (intem.RightEyeRemarks !== '') {
                    strPosteriorREye += intem.RightEyeRemarks;
                }

                if (intem.LeftEyeCdRatio !== '') {
                    strPosteriorLEye += 'CD Ratio : ' + intem.LeftEyeCdRatio + '\n';
                }
                if (intem.LeftEyeFreq !== '' && intem.LeftEyeFreq !== 0) {
                    strPosteriorLEye += 'Frequency : ' + (intem.LeftEyeFreq === 'positive' ? 'FR+' : 'FR-') + '\n';
                }
                if (intem.LeftEyeRemarks !== '') {
                    strPosteriorLEye += intem.LeftEyeRemarks;
                }
                invItem.push({
                    text: strPosteriorREye ? strPosteriorREye : 'N/A',
                    color: 'black',
                    fontSize: cFont,
                    bold: false
                });
                invItem.push({
                    text: strPosteriorLEye ? strPosteriorLEye : 'N/A',
                    color: 'black',
                    fontSize: cFont,
                    bold: false
                });
                bodyItem.push(invItem);

            });
        }
        if (bodyItem.length === 0)
            return null;
        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                widths: '*',
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'gray' : 'gray';
                }
            }
        };
        return patientLabTestTable;
    }

    function getNewFollowupDetailsprint(localArray) {
        var cBold = true;
        var cFont = 9;
        var hFont = 10;
        var headingFlag = 0;
        var invItem = [];
        var bodyItem = [];
        var invItem2 = [];
        if (localArray === undefined || localArray.length === 0)
            return;

        angular.forEach(localArray, function (item) {
            invItem.push({
                text: item.FollowUpDesc + item.FollowUpDate + ' ( ' + item.FollowUpDuration + " " + item.FollowUpDurationTypeName + ' ) ' + '\n', margin: [0, 0, 0, 5], bold: true
            });
            item.FollowUpNotes = item.FollowUpNotes || "";
            if (item.FollowUpNotes !== "") {
                invItem.push({
                    text: [{ text: 'Notes :', fontSize: hFont }, { text: ' ' + item.FollowUpNotes + '\n', fontSize: cFont }], margin: [0, 0, 0, 5], listType: 'none'
                });
            }
        });
        invItem2.push({ text: 'FollowUp Details', bold: true, fontSize: hFont });
        invItem2.push({ text: ':', bold: true, fontSize: hFont });
        invItem2.push({ text: invItem, fontSize: cFont });
        bodyItem.push(invItem2);

        var patientLabTestTable = {
            style: 'tableExample1',
            table: {
                widths: [120, 5, 410],
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.1 : 0.1;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },

                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'white' : 'white';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'white' : 'white';
                }
            }
        };
        return patientLabTestTable;
    }



