    function getNewTaperDrop(obj) {
        var cBold = false;
        var cFont = defaultFontSize;
        if (contentSetting.patientLabTest) {
            cBold = contentSetting.patientLabTest.isBold === "Y";
            cFont = contentSetting.patientLabTest.fontSize;
        }
        var hFont = 10;
        var cFont = 9;
        var headingFlag = 0;
        var bodyItem = [];

        var citem = "";
        var invItem1 = [];



        angular.forEach(obj, function (itm) {
            if (itm.PrescriptionData != undefined) {
                if (itm.PrescriptionData.ActiveInd === 'Y') {
                    var invItem3 = [{
                        type: 'round',
                        ul: [],
                        fontSize: 10

                    }];

                    var EyeName = "";

                    if (itm.PrescriptionData.OrganId === "1" || itm.PrescriptionData.OrganId === 1) {
                        EyeName = "( Right Eye)";
                    }
                    else if (itm.PrescriptionData.OrganId === "2" || itm.PrescriptionData.OrganId === 2) {
                        EyeName = "( Left Eye)";
                    }
                    else if (itm.PrescriptionData.OrganId === "3" || itm.PrescriptionData.OrganId === 3) {
                        EyeName = "( Both Eyes)";
                    }
                    else if (itm.PrescriptionData.OrganId === "4" || itm.PrescriptionData.OrganId === 4) {
                        EyeName = "";
                    }
                    else if (itm.PrescriptionData.OrganId === "5" || itm.PrescriptionData.OrganId === 5) {
                        EyeName = "( Hair)";
                    }
                    else if (itm.PrescriptionData.OrganId === "6" || itm.PrescriptionData.OrganId === 6) {
                        EyeName = "( Skin)";
                    }
                    else if (itm.PrescriptionData.OrganId === "7" || itm.PrescriptionData.OrganId === 7) {
                        EyeName = "( Laser)";
                    }


                    //  invItem1.push(EyeName + itm.PrescriptionData.Name);
                    //invItem1.push({
                    //    text: [{ text: EyeName + itm.PrescriptionData.Name, fontSize: cFont, bold: true }, { text: '\n' + sitem, fontSize: cFont, bold: false }], fontSize: cFont
                    //});
                    var invItem2 = [];

                    //var sitem = "";
                    //sitem = invItem2.join(", ");
                    var patientdocDetailsArray1 = [];

                    patientdocDetailsArray1.push({
                        text: [{ text: EyeName + itm.PrescriptionData.Name, fontSize: cFont, bold: true }], fontSize: cFont
                    });

                    bodyItem.push(patientdocDetailsArray1);
                    angular.forEach(itm.PrescriptionData.TaperingArray, function (preitem) {
                        if (preitem.ActiveInd === 'Y') {
                            invItem3[0].ul.push({
                                text: [
                                    { text: preitem.Frequency1 + '- ' + preitem.Dosage + '-' + preitem.Frequency2 + '-' + preitem.Duration + '- ' + preitem.DurationTypeName, color: 'black', bold: true, fontSize: cFont }
                                ]
                            });
                        }
                        bodyItem.push(invItem3);
                    });
                }
            }
            else {
                if (itm.ActiveInd === 'Y') {
                    var invItem3 = [{
                        type: 'round',
                        ul: [],
                        fontSize: 10

                    }];
                    var EyeName = "";

                    if (itm.OrganId === "1" || itm.OrganId === 1) {
                        EyeName = "( Right Eye)";
                    }
                    else if (itm.OrganId === "2" || itm.OrganId === 2) {
                        EyeName = "( Left Eye)";
                    }
                    else if (itm.OrganId === "3" || itm.OrganId === 3) {
                        EyeName = "( Both Eyes)";
                    }
                    else if (itm.OrganId === "4" || itm.OrganId === 4) {
                        EyeName = "";
                    }
                    else if (itm.OrganId === "5" || itm.OrganId === 5) {
                        EyeName = "( Hair)";
                    }
                    else if (itm.OrganId === "6" || itm.OrganId === 6) {
                        EyeName = "( Skin)";
                    }
                    else if (itm.OrganId === "7" || itm.OrganId === 7) {
                        EyeName = "( Laser)";
                    }
                    //var invItem2 = [];

                    //var sitem = "";

                    //sitem = invItem2.join(", ");
                    var patientdocDetailsArray1 = [];

                    patientdocDetailsArray1.push({
                        text: [{ text: EyeName + itm.Name, fontSize: cFont, bold: true }], fontSize: cFont
                    });

                    bodyItem.push(patientdocDetailsArray1);

                    angular.forEach(itm.TaperingArray, function (preitem) {
                        var DurationType = "";
                        if (preitem.DurationType === "D") {
                            DurationType = "Day(s)";
                        }
                        if (preitem.DurationType === "M") {
                            DurationType = "Month(s)";
                        }
                        if (preitem.DurationType === "W") {
                            DurationType = "Week(s)";
                        }
                        if (preitem.DurationType === "Y") {
                            DurationType = "Year(s)";
                        }
                        if (preitem.DurationType === "C") {
                            DurationType = "To Be continued";
                        }
                        if (preitem.DurationType === "L") {
                            DurationType = "Life Time";
                        }
                        // invItem2.push(preitem.Frequency1 + '- ' + preitem.Dosage + '-' + preitem.Frequency2 + '-' + preitem.Duration + '- ' + preitem.DurationType);
                        invItem3[0].ul.push({
                            text: [
                                { text: preitem.Frequency1 + '- ' + preitem.Dosage + '-' + preitem.Frequency2 + '-' + preitem.Duration + '- ' + DurationType, color: 'black', bold: true, fontSize: cFont }
                            ]
                        });
                        bodyItem.push(invItem3);
                    });
                }
            }
        });

        if (bodyItem.length === 0) {
            return null;
        }


        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                //widths: [300, '*'],
                widths: ['*'],
                //heights: 5,
                body: bodyItem
            },
            layout: 'noBorders'
        };
        return patientLabTestTable;
    }


