    function getPostMydriaticTestRows(refractionItem) {
        var cacheStorageItem = [];
        angular.forEach(refractionItem, function (item) {
            if (item.type === 'PostMydriaticTest') {
                cacheStorageItem = item.bindArray;
            }
        });
        var cBold = true;
        var cFont = defaultFontSize;
        if (cacheStorageItem.length === 0)
            return;

        cacheStorageItem[0].RightEye.Spherical = cacheStorageItem[0].RightEye.Spherical || "";
        cacheStorageItem[0].RightEye.Cylindrical = cacheStorageItem[0].RightEye.Cylindrical || "";
        cacheStorageItem[0].RightEye.Axis = cacheStorageItem[0].RightEye.Axis || "";
        cacheStorageItem[0].RightEye.Adition = cacheStorageItem[0].RightEye.Adition || "";
        cacheStorageItem[0].RightEye.BCVA = cacheStorageItem[0].RightEye.BCVA || "";
        cacheStorageItem[0].RightEye.BCNVA = cacheStorageItem[0].RightEye.BCNVA || "";

        cacheStorageItem[0].LeftEye.Spherical = cacheStorageItem[0].LeftEye.Spherical || "";
        cacheStorageItem[0].LeftEye.Cylindrical = cacheStorageItem[0].LeftEye.Cylindrical || "";
        cacheStorageItem[0].LeftEye.Axis = cacheStorageItem[0].LeftEye.Axis || "";
        cacheStorageItem[0].LeftEye.Adition = cacheStorageItem[0].LeftEye.Adition || "";
        cacheStorageItem[0].LeftEye.BCVA = cacheStorageItem[0].LeftEye.BCVA || "";
        cacheStorageItem[0].LeftEye.BCNVA = cacheStorageItem[0].LeftEye.BCNVA || "";
        cacheStorageItem[0].Remarks = cacheStorageItem[0].Remarks || "";

        if (cacheStorageItem[0].RightEye.Spherical === "" && cacheStorageItem[0].RightEye.Cylindrical === "" && cacheStorageItem[0].RightEye.Axis === "" && cacheStorageItem[0].RightEye.Adition === "" && cacheStorageItem[0].RightEye.RBCVA === "" && cacheStorageItem[0].RightEye.BCNVA === "" && cacheStorageItem[0].LeftEye.Spherical === "" && cacheStorageItem[0].LeftEye.Cylindrical === "" && cacheStorageItem[0].LeftEye.Axis === "" && cacheStorageItem[0].LeftEye.Adition === "" && cacheStorageItem[0].LeftEye.BCVA === "" && cacheStorageItem[0].LeftEye.BCNVA === "" && cacheStorageItem[0].Remarks === "")
            return;

        var invlist = false;

        if (cacheStorageItem[0].RightEye.Spherical === "" && cacheStorageItem[0].RightEye.Cylindrical === "" && cacheStorageItem[0].RightEye.Axis === "" && cacheStorageItem[0].RightEye.Adition === "" && cacheStorageItem[0].RightEye.BCVA === "" && cacheStorageItem[0].RightEye.BCNVA === "" && cacheStorageItem[0].LeftEye.Spherical === "" && cacheStorageItem[0].LeftEye.Cylindrical === "" && cacheStorageItem[0].LeftEye.Axis === "" && cacheStorageItem[0].LeftEye.Adition === "" && cacheStorageItem[0].LeftEye.BCVA === "" && cacheStorageItem[0].LeftEye.BCNVA === "") {
            invlist = true;
        }
        var cFont = 9;
        var hFont = 10;

        var bodyItem = [
            // [{ text: 'Post Mydriatic Test'.toUpperCase(), Roboto: true, fontSize: 10, color: 'black', bold: true }, {}, {}, {}, {}, {}, {}]
            [{ text: 'Post Mydriatic Test'.toUpperCase(), colSpan: 3, Roboto: true, fontSize: 10, color: 'black', border: [false, false, false, false], bold: true }, {}, {}, { text: '', colSpan: 4, color: 'black', fontSize: 10, bold: cBold, border: [false, false, false, false] }, {}, {}, {}]
        ];




        if (!invlist) {
            angular.forEach(cacheStorageItem, function (initem) {
                var invItem = [];
                invItem.push({
                    text: 'Eyes',
                    color: 'black',
                    fontSize: cFont,
                    bold: cBold
                });

                invItem.push({ text: 'SPH', color: 'black', fontSize: cFont, bold: cBold, alignment: 'center' });
                invItem.push({ text: 'CYL', color: 'black', fontSize: cFont, bold: cBold, alignment: 'center' });
                invItem.push({ text: 'Axis', color: 'black', fontSize: cFont, bold: cBold, alignment: 'center' });
                invItem.push({ text: 'ADD', color: 'black', fontSize: cFont, bold: cBold, alignment: 'center' });
                invItem.push({ text: 'BCVA', color: 'black', fontSize: cFont, bold: cBold, alignment: 'center' });
                invItem.push({ text: 'BCNVA', color: 'black', fontSize: cFont, bold: cBold, alignment: 'center' });

                bodyItem.push(invItem);



                var invItem1 = [];
                invItem1.push({
                    text: 'Right Eye'.toUpperCase(),
                    color: 'black',
                    fontSize: cFont,
                    bold: cBold
                });

                invItem1.push({ text: initem.RightEye.Spherical, color: 'black', fontSize: cFont, alignment: 'center' });
                invItem1.push({ text: initem.RightEye.Cylindrical, color: 'black', fontSize: cFont, alignment: 'center' });
                invItem1.push({ text: initem.RightEye.Axis, color: 'black', fontSize: cFont, alignment: 'center' });
                invItem1.push({ text: initem.RightEye.Adition, color: 'black', fontSize: cFont, alignment: 'center' });
                invItem1.push({ text: initem.RightEye.BCVA, color: 'black', fontSize: cFont, alignment: 'center' });
                invItem1.push({ text: initem.RightEye.BCNVA, color: 'black', fontSize: cFont, alignment: 'center' });

                bodyItem.push(invItem1);

                var invItem2 = [];

                invItem2.push({ text: 'Left Eye'.toUpperCase(), color: 'black', fontSize: cFont, bold: cBold });

                invItem2.push({ text: initem.LeftEye.Spherical, color: 'black', fontSize: cFont, alignment: 'center' });
                invItem2.push({ text: initem.LeftEye.Cylindrical, color: 'black', fontSize: cFont, alignment: 'center' });
                invItem2.push({ text: initem.LeftEye.Axis, color: 'black', fontSize: cFont, alignment: 'center' });
                invItem2.push({ text: initem.LeftEye.Adition, color: 'black', fontSize: cFont, alignment: 'center' });
                invItem2.push({ text: initem.LeftEye.BCVA, color: 'black', fontSize: cFont, alignment: 'center' });
                invItem2.push({ text: initem.LeftEye.BCNVA, color: 'black', fontSize: cFont, alignment: 'center' });

                bodyItem.push(invItem2);
            });
        }

        var invItem4 = [];
        cacheStorageItem[0].Remarks = cacheStorageItem[0].Remarks || "";
        if (cacheStorageItem[0].Remarks !== "") {
            invItem4.push({ text: 'Remarks : ' + cacheStorageItem[0].Remarks, colSpan: 7, color: '#686868', fontSize: cFont, bold: false, border: [true, true, true, true] }, {}, {}, {}, {}, {}, {});
            bodyItem.push(invItem4);
        }

        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                widths: '*',
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'gray' : 'gray';
                }
            }
        };
        return patientLabTestTable;
    }


