                    invItem3.push({ text: initem.InvestigationDesc + (initem.Value === '1' ? '( 38 cm)' : (initem.Value === '2' ? '( 55cm)' : (initem.Value === '3' ? '( 84cm)' : ''))), fontSize: cFont, bold: cBold });
