    function getPatientA6list(patientinfo) {
        var cFont = defaultFontSize;
        var cBold = true;
        var patientdocDetailsArray1 = [];
        patientdocDetailsArray1.push(
            [{ text: 'Patient Name', fontSize: cFont, bold: true, border: [false, false, false, false] }, { text: ':', fontSize: cFont, bold: true, border: [false, false, false, false] }, { text: patientinfo.PatientDetails.Title + ' ' + patientinfo.PatientDetails.FullName, fontSize: cFont, bold: false, alignment: 'left', border: [false, false, false, false] }],
            [{ text: 'Age/Gender', fontSize: cFont, bold: true, border: [false, false, false, false] }, { text: ':', fontSize: cFont, bold: true, border: [false, false, false, false] }, { text: patientinfo.PatientDetails.AgeInYears + 'Y' + ' ' + patientinfo.PatientDetails.AgeInMonths + 'M' + '/' + patientinfo.PatientDetails.Gender, fontSize: cFont, bold: false, alignment: 'left', border: [false, false, false, false] }],
            [{ text: 'MR NO', fontSize: cFont, bold: true, border: [false, false, false, false] }, { text: ':', fontSize: cFont, bold: true, border: [false, false, false, false] }, { text: patientinfo.PatientDetails.PatientDisplayId, fontSize: cFont, bold: false, alignment: 'left', border: [false, false, false, false] }]
        );

        var object = {
            table: {
                widths: [90, 5, 150],
                body: patientdocDetailsArray1
            },
            layout: 'noBorders'

        };

        return object;
    }

