    function getInvA6NewGlasses(cacheStorageItem, headingName) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (cacheStorageItem && cacheStorageItem.length === 0) {
            return;
        }
        var cFont = defaultFontSize;
        var hFont = 10;
        var cFont = 9;
        var headingFlag = 0;

        var bodyItem = [
            [
                {
                    text: '',
                    alignment: 'center',
                    bold: true,
                    fontSize: hFont,
                    fillColor: '#d3d3d8'
                },
                {
                    text: 'Sph',
                    alignment: 'center',
                    bold: true,
                    fontSize: hFont,
                    fillColor: '#d3d3d8'
                },

                {
                    text: 'Cyl',
                    alignment: 'center',
                    bold: true,
                    fontSize: hFont,
                    fillColor: '#d3d3d8'
                },
                {
                    text: 'Axis',
                    alignment: 'center',
                    bold: true,
                    fontSize: hFont,
                    fillColor: '#d3d3d8'
                }
            ]
        ];
        var invItem1 = [];
        invItem1.push({
            text: 'Right Eye',
            color: 'black',
            fontSize: cFont,
            alignment: 'center',
            bold: true
        });

        invItem1.push({ text: checkVal(cacheStorageItem[0].RightEyeValues.Spherical), fontSize: cFont, alignment: 'center' });
        invItem1.push({
            text: checkVal(cacheStorageItem[0].RightEyeValues.Cylindrical),
            fontSize: cFont,
            alignment: 'center'
        });
        invItem1.push({
            text: checkVal(cacheStorageItem[0].RightEyeValues.Axis),
            fontSize: cFont,
            alignment: 'center'

        });
        bodyItem.push(invItem1);

        var invItem2 = [];
        invItem2.push({
            text: 'Left Eye',
            fontSize: cFont,
            alignment: 'center',
            bold: true
        });


        invItem2.push({ text: checkVal(cacheStorageItem[0].LeftEyeValues.Spherical), fontSize: cFont, alignment: 'center' });

        invItem2.push({
            text: checkVal(cacheStorageItem[0].LeftEyeValues.Cylindrical),
            fontSize: cFont,
            alignment: 'center'

        });
        invItem2.push({
            text: checkVal(cacheStorageItem[0].LeftEyeValues.Axis),
            fontSize: cFont,
            alignment: 'center'
        });
        bodyItem.push(invItem2);

        if (bodyItem.length === 1) {
            return null;
        }

        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                widths: [50, 80, 37, 37],
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'grey' : 'grey';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'grey' : 'grey';
                }
            }
        };
        return patientLabTestTable;
    }
    function getInvA6NewGlassesIPD(cacheStorageItem) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (cacheStorageItem && cacheStorageItem.length === 0) {
            return;
        }
        var cFont = defaultFontSize;
        var hFont = 10;
        var cFont = 9;
        var headingFlag = 0;

        var bodyItem = [];
        var invItem1 = [];
        var sitem = "";
        angular.forEach(cacheStorageItem, function (item) {
            sitem = item.IPD;
        });
        if (sitem !== "") {
            invItem1.push({ text: 'Glass IPD : ', bold: true, fontSize: hFont });
            invItem1.push({ text: sitem, fontSize: cFont });
            bodyItem.push(invItem1);
        }

        if (bodyItem.length === 1) {
            return null;
        }

        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                widths: '*',
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'grey' : 'grey';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'grey' : 'grey';
                }
            }
        };
        return patientLabTestTable;
    }
