    this.generateNewDentalConsultationPrint = function (printObj) {
        var printArray = [];
        if (printObj.vitals && printObj.vitals.length > 0) {
            printArray.push(getNewParameterTable(printObj.vitals));
        }
        if ((printObj.ChiefComplaint && printObj.ChiefComplaint.length > 0) || (printObj.observations && printObj.observations.length > 0) || (printObj.clinicalNotes && printObj.clinicalNotes.length > 0) || (printObj.medicalHistory && printObj.medicalHistory.length > 0)) {
            printArray.push(getnewBasicInfoTable(printObj));
        }

        if (printObj.ChiefComplaint && printObj.ChiefComplaint.length > 0) {
            printArray.push(getNewChiefComplaint(printObj.ChiefComplaint));
        }
        if (printObj.clinicalNotes && printObj.clinicalNotes.length > 0) {
            printArray.push(getNewClinicalNotes(printObj.clinicalNotes));
        }
        if (printObj.observations && printObj.observations.length > 0) {
            printArray.push(getNewObservations(printObj.observations));
        }
        //if ((printObj.medicalConditions && printObj.medicalConditions.length > 0) || (printObj.medicalHistory && printObj.medicalHistory.length > 0) || (printObj.allergies && printObj.allergies.length > 0)) {
        //    printArray.push(getnewPastHistoryInfoTable(printObj));
        //}

        if (printObj.medicalConditions && printObj.medicalConditions.length > 0) {
            printArray.push(getNewMedicalConditions(printObj.medicalConditions));
        }

        if (printObj.medicalHistory && printObj.medicalHistory.length > 0) {
            printArray.push(getNewDentalMedicalHistory(printObj.medicalHistory));
        }

        if (printObj.allergies && printObj.allergies.length > 0) {
            printArray.push(getNewAllergies(printObj.allergies));
        }

        if (printObj.ToothProblem && printObj.ToothProblem.length > 0) {
            printArray.push(getNewToothProblemsStructure(printObj.ToothProblem, printObj.TreatmentFinalCost));
        }

        if ((printObj.provisionalDiagnosis && printObj.provisionalDiagnosis.length > 0) || (printObj.finalDiagnosis && printObj.finalDiagnosis.length > 0) || (printObj.treatment && printObj.treatment.length > 0 && printObj.treatment[0].length > 0) || (printObj.LabTest && printObj.LabTest.length > 0)) {
            printArray.push(getnewDiagnosisInfoTable(printObj));
        }


        if (printObj.provisionalDiagnosis && printObj.provisionalDiagnosis.length > 0) {
            printArray.push(getNewProvisionalListDiagnosis(printObj.provisionalDiagnosis, 'Provisional Diagnosis :'));
        }

        if (printObj.finalDiagnosis && printObj.finalDiagnosis.length > 0) {
            printArray.push(getNewActualListDiagnosis(printObj.finalDiagnosis, 'Actual Diagnosis :'));
        }

        if (printObj.prescription && printObj.prescription[0] && printObj.prescription.length > 0) {
            printArray.push(getNewPrescriptions(printObj.prescription));
        }

        var isArray = angular.isArray(printObj.followupObj);

        if (isArray === false && printObj.followupObj !== undefined) {
            if (printObj.followupObj.FollowUpDuration !== "") {
                printArray.push(getFollowupprint(printObj.followupObj));
            }
        }
        if (printObj.DoctorSignature) {
            var doctorinfo = eHnoteMasterDataService.getUserInfo();
            // printArray.push(getsignatureRows(printObj.DoctorSignature));
            printArray.push(getSurgeryDoctorSignatureInfodental(printObj.DoctorSignature, doctorinfo));
        }
        var headingName = printObj.pageType === 'viewCase' ? 'CASE HISTORY REPORT' : 'CONSULTATION REPORT';
        var printType = 'Summary';
        if (printObj.pageType) {
            printType = printObj.pageType === 'viewCase' ? 'ViewCaseHistory' : 'Summary';
        }
        commonDentalPrintWithArrary(printObj, printArray, headingName, printType);
    };

