    function getChiefComplaint(localArray) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (localArray === undefined || localArray.length === 0)
            return;
        var cFont = 8;
        var hFont = 9;

        var bodyItem = [
            [{
                text: 'Chief Complaints :', fontSize: 10, bold: true, margin: [0, 0, 0, 5]
            }]
        ];

        var headingFlag = 0;
        var invItem1 = [{
            type: 'circle',
            ul: [],
            fontSize: 8

        }];
        angular.forEach(localArray, function (item) {

            invItem1[0].ul.push({
                text: item.Notes, margin: [0, 0, 0, 5]
            });

        });
        if (invItem1[0].ul.length > 0) {
            bodyItem.push(invItem1);
        }
        if (bodyItem.length === 1)
            return null;
        return bodyItem;
    }

    function getNewChiefComplaint(localArray) {
        var cBold = true;
        var cFont = 9;
        var hFont = 10;
        var headingFlag = 0;
        var sitem = "";
        if (localArray === undefined || localArray.length === 0)
            return;
        var invItem1 = [];
        var bodyItem = [];
        var invItem2 = [];

        var doctorinfo = eHnoteMasterDataService.getUserInfo();
        var SpecializationId = doctorinfo.doctordata.User[0].SpecializationId;

        if (SpecializationId === 2 || SpecializationId === 9) {
            angular.forEach(localArray, function (item) {
                item.ActiveInd = 'Y';
                item.OrganId = 4;
            });
        }
        angular.forEach(localArray, function (item) {
            if (item.ActiveInd === 'Y') {
                //  var organName = item.OrganId === 1 ? 'Right Eye : ' : (item.OrganId === 2 ? 'Left Eye : ' : 'Both Eyes : ');

                //var organName = item.OrganId === 1 ? 'Right Eye : ' : item.OrganId === 2 ? 'Left Eye : ' : item.OrganId === 3 ? 'Both Eyes : ' : item.OrganId === 5 ? 'Hair : ' : (item.OrganId === 6 ? 'Skin : ' : 'Laser : ');
                var organName = item.OrganId === 1 ? 'Right Eye : ' : item.OrganId === 2 ? 'Left Eye : ' : item.OrganId === 3 ? 'Both Eyes : ' : item.OrganId === 5 ? 'Hair : ' : item.OrganId === 6 ? 'Skin : ' : (item.OrganId === 7 ? 'Laser : ' : '');
                var Duartionlist = "";
                var list1, list2 = "";
                item.Duration = item.Duration || 0;
                if (item.Duration != 0) {
                    list1 = ' from ' + item.Duration;
                    list2 = item.DurationType === 'D' ? 'Day(s)' : (item.DurationType === 'W' ? 'Week(s)' : (item.DurationType === 'M' ? 'Month(s)' : (item.DurationType === 'Y' ? 'Year(s)' : '')));
                    Duartionlist = list1 + ' ' + list2;
                }

                if (item.ChiefComplaintName !== "") {
                    if (item.OrganId === 4) {

                        //invItem1.push({
                        //    text: item.Notes + ' .' + '\n', margin: [0, 0, 0, 5], fontSize: cFont, bold: false
                        //});

                        invItem1.push({ text: [{ text: item.ChiefComplaintName, bold: false, fontSize: cFont }, { text: Duartionlist + ' .' + '\n', margin: [0, 0, 0, 5], fontSize: cFont, bold: true }] });
                    }
                    else {

                        invItem1.push({
                            text: [
                                { text: organName, color: 'black', bold: true, fontSize: cFont },
                                { text: item.ChiefComplaintName, color: 'black', bold: false, fontSize: cFont },
                                { text: Duartionlist + ' .' + '\n', color: 'black', bold: true, fontSize: cFont }
                            ]
                        });

                    }
                }
            }
        });
        if (invItem1.length != 0) {
            invItem2.push({ text: 'Chief Complaints', bold: true, fontSize: hFont });
            invItem2.push({ text: ':', bold: true, fontSize: hFont });
            invItem2.push({ text: invItem1, fontSize: cFont });
            bodyItem.push(invItem2);

            var patientLabTestTable = {
                style: 'tableExample1',
                table: {
                    widths: [120, 5, 410],
                    body: bodyItem
                },
                layout: {
                    hLineWidth: function (i, node) {
                        return (i === 0 || i === node.table.body.length) ? 0.1 : 0.1;
                    },
                    vLineWidth: function (i, node) {
                        return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                    },
                    hLineColor: function (i, node) {
                        return (i === 0 || i === node.table.body.length) ? 'white' : 'white';
                    },
                    vLineColor: function (i, node) {
                        return (i === 0 || i === node.table.widths.length) ? 'white' : 'white';
                    }
                }
            };
            return patientLabTestTable;
        }
    }
