    function getNewAdditionalInvRows(additem) {
        var cacheStorageItem = [];
        angular.forEach(additem, function (item) {
            if (item.type === 'AdditionalInvestgation') {
                cacheStorageItem = item.bindArray;
            }
        });
        var cBold = true;
        var cFont = defaultFontSize;

        if (cacheStorageItem && cacheStorageItem.length === 0)
            return;
        var cFont = 9;
        var hFont = 10;

        var bodyItem = [
            [
                {
                    text: ' Investigations',
                    alignment: 'center',
                    fillColor: '#d3d3d8',
                    bold: true,
                    fontSize: hFont
                },
                {
                    text: 'Right Eye(OD)',
                    alignment: 'center',
                    fillColor: '#d3d3d8',
                    bold: true,
                    fontSize: hFont
                },
                {
                    text: 'Left Eye(OS)', alignment: 'center', fillColor: '#d3d3d8', bold: true,
                    fontSize: hFont
                }
            ]
        ];

        var strAditionalREye = "";
        var strAditionalLEye = "";
        angular.forEach(cacheStorageItem, function (intem) {

            if (intem.CategoryId === null) {
                return;
            }
            else {
                var strAditionalREye = "";
                var strAditionalLEye = "";
                var invItem = [];
                invItem.push({
                    text: intem.InvestigationDesc,
                    color: 'black',
                    fontSize: cFont,
                    bold: cBold
                });
                if (intem.InvestigationDetails.RightEyeCdRatio !== '') {
                    strAditionalREye += 'CD Ratio : ' + intem.InvestigationDetails.RightEyeCdRatio + '\n';
                }
                if (intem.InvestigationDetails.RightEyeFreq !== '') {
                    strAditionalREye += 'Frequency :  ' + (intem.InvestigationDetails.RightEyeFreq === 'positive' ? 'FR+' : 'FR-') + '\n';
                }
                if (intem.InvestigationDetails.RightEye !== '') {
                    strAditionalREye += intem.InvestigationDetails.RightEye;
                }

                if (intem.InvestigationDetails.LeftEyeCdRatio !== '') {
                    strAditionalLEye += 'CD Ratio :  ' + intem.InvestigationDetails.LeftEyeCdRatio + '\n';
                }
                if (intem.InvestigationDetails.LeftEyeFreq !== '') {
                    strAditionalLEye += 'Frequency :   ' + (intem.InvestigationDetails.LeftEyeFreq === 'positive' ? 'FR+' : 'FR-') + '\n';
                }
                if (intem.InvestigationDetails.LeftEye !== '') {
                    strAditionalLEye += intem.InvestigationDetails.LeftEye;
                }
                invItem.push({
                    text: strAditionalREye ? strAditionalREye : 'N/A',
                    color: 'black',
                    fontSize: cFont,
                    bold: false
                });
                invItem.push({
                    text: strAditionalLEye ? strAditionalLEye : 'N/A',
                    color: 'black',
                    fontSize: cFont,
                    bold: false
                });
                bodyItem.push(invItem);
            }
        });

        if (bodyItem.length === 1)
            return null;
        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                widths: '*',
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'gray' : 'gray';
                }
            }
        };
        return patientLabTestTable;
    }


