    function getNewDiagnosis(localArray, type) {
        var doctorinfo = eHnoteMasterDataService.getUserInfo();
        var SpecializationId = doctorinfo.doctordata.User[0].SpecializationId;
        var cBold = true;
        var cFont = defaultFontSize;
        if (localArray === undefined || localArray.length === 0)
            return;
        var cFont = 8;
        var hFont = 9;

        var bodyItem = [
            [{
                text: type,
                fillColor: '#eaeaea',
                bold: true,
                margin: [0, 5, 0, 5],
                fontSize: 10
            }]
        ];

        var headingFlag = 0;
        var invItem1 = [{
            type: 'circle',
            ul: [],
            fontSize: 8

        }];

        angular.forEach(localArray, function (item) {


            var name = '', organName = '', notes = '';
            if (item.DiagnosisData === undefined) {
                name = item.DiagnosisName;
                organName = item.OrganName;
                notes = item.DiagnosisNotes ? item.DiagnosisNotes : '';
            }
            else {
                name = item.DiagnosisData.DiagnosisName;
                organName = item.OrganName;
                notes = item.DiagnosisData.DiagnosisNotes ? item.DiagnosisData.DiagnosisNotes : '';
            }

            if (item.DiagnosisName) {
                name = item.DiagnosisName;
                organName = item.OrganId === 1 ? 'Right eye' : (item.OrganId === 2 ? 'Left eye' : 'Both eyes');
            }


            if (SpecializationId === 2) {
                invItem1[0].ul.push({
                    text: name + (item.Teethno ? (' for Teeths ' + item.Teethno) : ''), margin: [0, 0, 0, 5]
                });
            }
            else {
                if (item.OrganId === 4) {
                    invItem1[0].ul.push({
                        text: name, margin: [0, 0, 0, 5]
                    });
                }
                else {
                    invItem1[0].ul.push({
                        text: name + ' for ' + organName, margin: [0, 0, 0, 5]
                    });
                }
            }
            if (notes !== '') {
                invItem1[0].ul.push({
                    text: [{ text: 'Notes :', fontSize: 9, bold: true }, { text: ' ' + notes, fontSize: 8 }], margin: [0, 0, 0, 5], listType: 'none'

                });
            }
        });
        if (invItem1[0].ul.length > 0) {
            bodyItem.push(invItem1);
        }

        if (bodyItem.length === 1)
            return null;
        return bodyItem;
    }

