    function getClinicalNotes(localArray) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (localArray === undefined || localArray.length === 0)
            return;
        var cFont = 8;
        var hFont = 9;
        var bodyItem = [
            [{
                text: 'Clinical Notes :',
                fillColor: '#eaeaea',
                bold: true,
                margin: [0, 5, 0, 5],
                fontSize: 10
            }]
        ];
        var headingFlag = 0;
        var invItem1 = [{
            type: 'circle',
            ul: [],
            fontSize: 8

        }];
        angular.forEach(localArray, function (item) {

            invItem1[0].ul.push({
                text: item.Notes, margin: [0, 0, 0, 5]
            });
        });
        if (invItem1[0].ul.length > 0) {
            bodyItem.push(invItem1);
        }

        if (bodyItem.length === 1)
            return null;
        return bodyItem;
    }

