    function getTreatements(localArray) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (localArray === undefined || localArray.length === 0)
            return;
        var cFont = 9;
        var hFont = 10;

        var bodyItem = [
            [{ text: 'Treatment', bold: true, margin: [0, 5, 0, 5], fontSize: cFont, border: [false, false, false] },
            { text: 'Notes', bold: true, margin: [0, 5, 0, 5], fontSize: cFont, border: [false, false, false] }
            ]
        ];

        var headingFlag = 0;
        angular.forEach(localArray[0], function (item) {
            if (item.TreatmentData) {
                item.TreatmentData.OrganId = item.OrganId;
                item.TreatmentData.OrganName = item.OrganName;
                item = item.TreatmentData;
            }
            var ischeckprinttreat = item.ActiveInd === "Y";

            if (ischeckprinttreat) {
                if (item.OrganId) {
                    var organName = item.OrganId === '1' ? 'Right Eye' : (item.OrganId === '2' ? 'Left Eye' : (item.OrganId === '3' ? 'Both Eyes' : (item.OrganId === '4' ? 'General' : "")));
                } else if (item.OrganName) {
                    var organName = item.OrganName ? item.OrganName : item.OrganName;
                }

                var invItem1 = [];
                if (item.OrganId === 4) {
                    invItem1.push({
                        text: item.TreatmentName ? item.TreatmentName : '',
                        color: 'black',
                        fontSize: 8,
                        border: [false, true, false],
                        margin: [0, 5, 0, 5]
                    });
                }
                else {

                    invItem1.push({
                        text: item.TreatmentName ? item.TreatmentName + ' ' + 'for' + ' ' + organName : '',
                        color: 'black',
                        fontSize: 8,
                        border: [false, true, false],
                        margin: [0, 5, 0, 5]
                    });
                }
                var TreatmentNotes = "";

                TreatmentNotes = item.TreatmentNotes || "";

                invItem1.push({
                    text: TreatmentNotes,
                    color: 'black',
                    fontSize: 8,
                    border: [false, true, false],
                    margin: [0, 5, 0, 5]
                });
                if (invItem1.length > 0) {
                    bodyItem.push(invItem1);
                }
            }
        });

        if (bodyItem.length === 1)
            return null;

        var prescriptionTable = {
            style: 'tableExample',
            table: {
                widths: [150, 350],
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'gray' : 'gray';
                }
            }
        };
        var TreatArray = [];
        TreatArray.push(prescriptionTable);
        return TreatArray;
    }

