    this.generateNewConsentPrint = function (printObj) {

        var param = {
            "HospitalCD": "",
            "DoctorID": 3,
            "PageType": "PRINT",
            "IsDefault": "Y",
            "SubPageType": "SUMMARY",
            "IncludeBase64": "Y"
        };
        var data = printSettings;
        var pageSettings = {
            "marginLeft": 40,
            "marginTop": 100,
            "marginRight": 40,
            "marginBottom": 10
        };
        var headerHeight = 100;
        var footerHeight = 100;
        var docSign = "";
        var isDefaultDocSign = "";
        printPageSize = "A4";
        contentSetting = setContentSettings();
        if (data !== undefined) {
            pageSettings = data.JsonSetting.pageSettings;
            headerHeight = data.JsonSetting.clinicSettings.headerSettings.dimension.height;
            footerHeight = data.JsonSetting.clinicSettings.footerSettings.dimension.height;
            contentSetting = data.JsonSetting.clinicSettings.contentSettings;
            docSign = data.JsonSetting.clinicSettings.footerSettings.custFootSign;
            isDefaultDocSign = data.JsonSetting.clinicSettings.footerSettings.isFootSignDefault;
            if (data.JsonSetting.pageSettings.pageSize === "A4") {
                defaultFontSize = 10;
            } else {
                printPageSize = "A5";
                defaultFontSize = 8;
            }
        }
        var content = [];
        var printSettingInfo = eHnoteMasterDataService.getPrintSettingSpecific('Summary').PageSettings;
        var invItems = getConsentImagesRows(printObj);
        if (invItems === undefined || invItems === "" || invItems === null) { } else {
            content.push(invItems);
        }
        var docdefination = {
            header: function (currentPage, pageCount) {
                var headerSetting = getHeader(data, printSettingInfo.MarginRight, printSettingInfo.PageOrientation);
                headerSetting.margin = [printSettingInfo.MarginLeft, printSettingInfo.MarginTop, printSettingInfo.MarginRight, 20];
                return headerSetting;
            },
            footer: function (currentPage, pageCount) {
                var footerSetting = getFooter(data, printSettingInfo.MarginRight, printSettingInfo.PageOrientation);
                footerSetting.margin = [printSettingInfo.MarginLeft, 5, printSettingInfo.MarginRight, printSettingInfo.MarginBottom];
                return footerSetting;
            },
            "pageMargins": [printSettingInfo.MarginLeft, headerHeight + printSettingInfo.MarginTop, printSettingInfo.MarginRight, footerHeight + printSettingInfo.MarginBottom],
            "pageSize": printSettingInfo.PageSize,
            "pageOrientation": printSettingInfo.PageOrientation,
            "content": content,
            "defaultStyle": {
                font: 'Roboto'
            },
            "styles": {
                "header": {
                    "fontSize": 18,
                    "bold": true,
                    "margin": [0, 0, 0, 10]
                },
                "titleHeader": {
                    "fontSize": 18,
                    "bold": true,
                    "alignment": 'left',
                    "margin": [40, 10, 10, 20],
                    "paddingBottom": 200
                },
                "footer": {
                    "alignment": 'right',
                    "margin": [20, 10, 40, 20]
                },
                "subheader": {
                    "fontSize": 16,
                    "bold": true,
                    "margin": [0, 10, 0, 5]
                },
                "tableExample": {
                    "margin": [0, 5, 0, 15]
                },
                "tableHeader": {
                    "bold": true,
                    "fontSize": 10,
                    "color": 'black'
                },
                "contentText": {
                    "fontSize": 10
                }
            }
        };
        pdfMake.createPdf(docdefination).print();
    };

    function getOpticalOrderDetailsArrayTable(item, margin) {
        var bitem = item.ConsumeStockDetails;
        var cBold = false;
        var cFont = defaultFontSize;
        if (contentSetting.patientBilling) {
            cBold = contentSetting.patientBilling.isBold === "Y";
            cFont = contentSetting.patientBilling.fontSize;
        }
        var bodyItem = [];
        var cFont = 9;
        var hFont = 10;
        var bodyItem = [
            [
                {
                    text: 'Category - Product - Model',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                },
                {
                    text: 'Qty',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                },
                {
                    text: 'MRP',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont,
                    margin: [5, 0, 0, 0]
                },
                {
                    text: 'GST',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                },
                {
                    text: 'Disc',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                },
                {
                    text: 'Amount',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                }
            ]
        ];

        angular.forEach(bitem, function (subitem) {
            var catglist = "";
            catglist = subitem.CategoryName;

            var productlist = "";
            if (subitem.ProductName !== "" && subitem.ProductName !== undefined) {
                productlist = '-' + subitem.ProductName;
            }
            var modelist = "";
            if (subitem.ModelName !== "" && subitem.ModelName !== undefined) {
                modelist = '-' + subitem.ModelName;
            }
            var totalItemList = "";
            totalItemList = catglist + productlist + modelist;
            var invarray1 = [];
            var DiscountType = subitem.DiscountType === "P" ? "%" : "INR";
            invarray1.push({ text: totalItemList, fontSize: cFont });
            invarray1.push({ text: subitem.AvailbaleQty === null ? '' : subitem.AvailbaleQty, fontSize: cFont });
            invarray1.push({ text: subitem.Price, fontSize: cFont });
            invarray1.push({ text: subitem.GST, fontSize: cFont });
            invarray1.push({ text: subitem.Discount + "(" + DiscountType + ")", fontSize: cFont });
            invarray1.push({ text: subitem.TotalAmount, fontSize: cFont });
            bodyItem.push(invarray1);
        });

        if (bodyItem.length === 1)
            return null;
        var patientBillingTable = {
            style: 'tableExample',
            table: {
                widths: [190, 40, 50, 50, 40, '*'],
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'gray' : 'gray';
                }
            }
        };
        return patientBillingTable;
    }


