    function getOpticalPurchaseDetailsArrayTable(item, margin) {
        var bitem = item.StockDetails;
        var cBold = false;
        var cFont = defaultFontSize;
        if (contentSetting.patientBilling) {
            cBold = contentSetting.patientBilling.isBold === "Y";
            cFont = contentSetting.patientBilling.fontSize;
        }
        var bodyItem = [];
        var cFont = 9;
        var hFont = 10;
        var modeofPayStringMain = "";
        var checkNum = "";
        angular.forEach(item.PaymentHistory, function (item) {
            var checkNo = "";
            item.Amount = parseFloat(item.Amount) || 0;
            if (item.Amount !== 0) {
                modeofPayStringMain += " By " + item.PaymentModeName + ": " + item.Amount;
                checkNo = item.ChequeNumber;
            }
            if (checkNo != null) {
                checkNum = ' Cheque Number : ' + checkNo;
            }
            else {
                checkNum = "";
            }
        });

        var bodyItem = [
            [
                {
                    text: 'Category - Product - Model',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                },
                {
                    text: "Type",
                    bold: true,
                    fillColor: "#d3d3d8",
                    fontSize: hFont
                },
                //{
                //    text: "Coating",
                //    bold: true,
                //    fillColor: "#d3d3d8",
                //    fontSize: hFont
                //},
                //{
                //    text: "Index",
                //    bold: true,
                //    fillColor: "#d3d3d8",
                //    fontSize: hFont
                //},
                //{
                //    text: "Power",
                //    bold: true,
                //    fillColor: "#d3d3d8",
                //    fontSize: hFont
                //},
                {
                    text: 'Qty',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                },
                {
                    text: 'Price',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont,
                    margin: [5, 0, 0, 0]
                },
                {
                    text: 'GST',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                },
                {
                    text: 'Disc',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                },
                {
                    text: 'Total',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                },
                {
                    text: 'Status',
                    bold: true,
                    fillColor: '#d3d3d8',
                    fontSize: hFont
                }
            ]

        ];

        angular.forEach(bitem, function (subitem) {
            var catglist = "";
            catglist = subitem.OptCatName;

            var productlist = "";
            if (subitem.OpticalItemName !== "" && subitem.OpticalItemName !== undefined) {
                productlist = '-' + subitem.OpticalItemName;
            }

            var modelist = "";
            if (subitem.ModelName !== "" && subitem.ModelName !== undefined) {
                modelist = '-' + subitem.ModelName;
            }

            var totalItemList = "";
            totalItemList = catglist + productlist + modelist;

            var status = "";
            if (subitem.ActiveInd === 'Y') {
                status = 'Active';
            }
            else {
                status = 'InActive';
            }
            var totalAmount = "";
            if (item.TotalAmount !== undefined) {
                totalAmount = item.TotalAmount;
            }
            var invarray1 = [];
            invarray1.push({ text: totalItemList, fontSize: cFont });
            invarray1.push({ text: subitem.LensTypeName, fontSize: cFont });
            //invarray1.push({ text: subitem.CoatingName, fontSize: cFont });
            //invarray1.push({ text: subitem.IndexName, fontSize: cFont });
            //invarray1.push({ text: subitem.PowerName, fontSize: cFont });
            invarray1.push({ text: subitem.Quantity === null ? '' : subitem.Quantity, fontSize: cFont });
            invarray1.push({ text: subitem.Price, fontSize: cFont });
            invarray1.push({ text: subitem.GST, fontSize: cFont });
            invarray1.push({ text: subitem.DiscountValue, fontSize: cFont });
            invarray1.push({ text: totalAmount, fontSize: cFont });
            invarray1.push({ text: status, fontSize: cFont });
            bodyItem.push(invarray1);

        });

        var invarray2 = [];
        invarray2.push({ text: 'Payment Details : ' + modeofPayStringMain + '', border: [false, false, false, false], fontSize: cFont, colSpan: 8, bold: true }, {}, {}, {}, {}, {}, {}, {});
        bodyItem.push(invarray2);

        if (checkNum != "") {
            var invarray3 = [];
            invarray3.push({ text: checkNum + '', border: [false, false, false, false], fontSize: cFont, colSpan: 8, bold: true }, {}, {}, {}, {}, {}, {}, {});
            bodyItem.push(invarray3);
        }

        if (bodyItem.length === 1)
            return null;
        var patientBillingTable = {
            style: 'tableExample',
            table: {
                widths: [170, 45, 30, 40, 25, 25, 50, '*'],
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'gray' : 'gray';
                }
            }
        };
        return patientBillingTable;
    }

