    function getDischargeOperativeInstructions(localArray, PrintLanguageId) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (localArray === undefined || localArray.length === 0)
            return;
        var cFont = 9;
        var hFont = 10;

        var bodyItem = [
            [{
                text: 'Advice on Discharge',
                fillColor: '#eaeaea',
                bold: true,
                margin: [0, 5, 0, 5],
                fontSize: hFont
            }]
        ];

        var headingFlag = 0;
        var invItem1 = [{
            type: 'square',
            ol: [],
            fontSize: cFont

        }];
        var sitem = "";

        if (PrintLanguageId === 1) {
            var obj = $filter("filter")(localArray.Instructions, { "Language": "en" })[0];

        } else if (PrintLanguageId === 2) {
            var obj = $filter("filter")(localArray.Instructions, { "Language": "ka" })[0];
        } else if (PrintLanguageId === 3) {
            var obj = $filter("filter")(localArray.Instructions, { "Language": "mr" })[0];
        } else if (PrintLanguageId === 4) {
            var obj = $filter("filter")(localArray.Instructions, { "Language": "te" })[0];
        } else if (PrintLanguageId === 5) {
            var obj = $filter("filter")(localArray.Instructions, { "Language": "hi" })[0];
        } else if (PrintLanguageId === 6) {
            var obj = $filter("filter")(localArray.Instructions, { "Language": "pa" })[0];
        }

        if (obj !== undefined) {

            sitem = obj.translateName;

            var list = [];
            list = sitem.split('~');
            angular.forEach(list, function (item) {
                if (item !== "") {
                    invItem1[0].ol.push({
                        text: [{ text: ' ' + item, fontSize: cFont, font: PrintLanguageId === 1 ? 'Roboto' : PrintLanguageId === 2 ? 'Kannada' : PrintLanguageId === 3 ? 'marati' : PrintLanguageId === 4 ? 'telugu' : PrintLanguageId === 5 ? "hindhi" : "Panjab" }], margin: [0, 0, 0, 5]
                    });
                }
            });

            if (invItem1[0].ol.length > 0) {
                bodyItem.push(invItem1);
            }
            if (bodyItem.length === 1)
                return null;
            return bodyItem;
        }
    }





