    function getDischargeFollowupprint(localArray) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (localArray === undefined || localArray.length === 0)
            return;
        var cFont = 8;
        var hFont = 9;

        var bodyItem = [
            [{
                text: '',
                bold: true,
                margin: [0, 5, 0, 5],
                fontSize: 10
            }]
        ];
        var headingFlag = 0;

        var invItem1 = [];
        if (localArray.FollowUpDate != "") {
            invItem1.push({
                text: [{ text: 'Follow-Up Date                         : ', fontSize: 9, bold: true }, { text: ' ' + localArray.FollowUpDate + ' ( ' + localArray.FollowUpDuration + " " + localArray.FollowUpDurationTypeName + ' ) ', fontSize: 8 }], margin: [5, 3, 0, 0]
            });
        }
        if (localArray.FollowUpNotes !== '' && localArray.FollowUpNotes !== undefined) {
            invItem1.push({
                text: [{ text: 'Follow-Up Notes                       : ', fontSize: 9, bold: true }, { text: ' ' + localArray.FollowUpNotes, fontSize: 8 }], margin: [5, 3, 0, 0]
            });
        }

        if (invItem1.length > 0) {
            bodyItem.push(invItem1);
        }

        if (bodyItem.length === 1)
            return null;
        return bodyItem;
    }

