    function getNewOtInvestigation(localArray) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (localArray === undefined || localArray.length === 0)
            return;
        var cFont = 9;
        var hFont = 10;
        var invItem1 = [];
        var bodyItem = [];
        var invItem2 = [];
        var bodyItem = [
            [{ text: "Investigation", bold: true, margin: [0, 5, 0, 5], fontSize: cFont, border: [false, false, false] },
            { text: 'Instructions', bold: true, margin: [0, 5, 0, 5], fontSize: cFont, border: [false, false, false] },
            { text: 'Result', bold: true, margin: [0, 5, 0, 5], fontSize: cFont, border: [false, false, false] }
            ]
        ];

        var headingFlag = 0;
        angular.forEach(localArray, function (item) {
            var invItem1 = [];
            invItem1.push({
                text: item.InvestigationName + ' .', margin: [0, 0, 0, 5], fontSize: cFont, bold: false, border: [false, true, false]
            });
            invItem1.push({
                text: item.InvestigationInstruction,
                color: 'black',
                fontSize: 8,
                border: [false, true, false],
                margin: [0, 5, 0, 5]
            });
            invItem1.push({
                text: item.Result,
                color: 'black',
                fontSize: 8,
                border: [false, true, false],
                margin: [0, 5, 0, 5]
            });

            if (invItem1.length > 0) {
                bodyItem.push(invItem1);
            }
        });

        if (bodyItem.length === 1)
            return null;

        var prescriptionTable = {
            style: 'tableExample',
            table: {
                widths: [150, 250, 100],
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'gray' : 'gray';
                }
            }
        };
        var TreatArray = [];
        TreatArray.push(prescriptionTable);
        return TreatArray;
    }

