    function GetIolConsumedTable(IolObject) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (IolObject === undefined || IolObject.length === 0) {
            return;
        }
        var cFont = 9;
        var hFont = 10;
        var bodyItem = [];
        var IolHeadingArray = [];
        IolHeadingArray.push({ text: 'IoL Details'.toUpperCase(), alignment: 'left', bold: true, fontSize: hFont, fillColor: '#d3d3d8', margin: [5, 2, 0, 2] },
            { text: '', alignment: 'center', bold: true, fontSize: hFont, fillColor: '#d3d3d8', margin: [0, 2, 0, 2] },
            { text: '', alignment: 'right', bold: true, fontSize: hFont, fillColor: '#d3d3d8', margin: [0, 2, 0, 2] }

        );

        bodyItem.push(IolHeadingArray);
        var IolArray = [];
        var IolArray1 = [];
        IolArray.push({ text: 'IOL NAME', fontSize: hFont, bold: true, alignment: 'left' }, { text: ':', fontSize: hFont, bold: true, alignment: 'center' },
            { text: IolObject.ItemName, bold: false, fontSize: hFont, alignment: 'left' },
        );
        bodyItem.push(IolArray);
        IolArray1.push({ text: 'Serial No', fontSize: hFont, bold: true, alignment: 'left' }, { text: ':', fontSize: hFont, bold: true, alignment: 'center' },
            { text: IolObject.BarCodesArray[0].BarCode, bold: false, fontSize: hFont, alignment: 'left' },
        );

        bodyItem.push(IolArray1);
        if (bodyItem.length === 1)
            return null;

        var IolArrayTable = {
            style: 'tableExample1',
            table: {
                widths: [170, 5, '*'],
                body: bodyItem
            },
            layout: 'noBorders'
        };

        console.log(JSON.stringify(IolArrayTable));
        return IolArrayTable;
    }


