    function getNewOtWardChecklist(localArray, type) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (localArray === undefined || localArray.length === 0) {
            return;
        }
        var cFont = 9;
        var hFont = 10;
        var bodyItem = [];

        var array_cleaned = [];
        if (type === 1) {
            var array_cleaned = localArray.CheckListData.filter(function (value, index) { return index < 10; });

        } else {
            var array_cleaned = localArray.CheckListData.filter(function (value, index) { return index >= 10; });
        }

        angular.forEach(array_cleaned, function (item) {
            var CheckListArray = [];
            //var AnsCheckList = "";
            //if (item.IsActive) {
            //    AnsCheckList = true;
            //} else {
            //    AnsCheckList = false;
            //}

            CheckListArray.push(

                { text: item.Description, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.IsActive ? 'Yes' : 'No', bold: true, fontSize: cFont, alignment: 'left' }

            );

            bodyItem.push(CheckListArray);
        });

        if (bodyItem.length === 1)
            return null;

        var ChecklistTable = {
            style: 'tableExample',
            table: {
                widths: ['*', 30],
                body: bodyItem
            }
        };
        return ChecklistTable;
    }


    function getNewOtPostOperativeChecklist(localArray) {
        var cBold = true;
        var cFont = defaultFontSize;
        if (localArray === undefined || localArray.length === 0) {
            return;
        }
        var cFont = 9;
        var hFont = 10;
        var bodyItem = [];

        angular.forEach(localArray.CheckListData.PostOperative, function (item) {
            var CheckListArray = [];
            CheckListArray.push(

                { text: item.Description, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.IsActive ? 'Yes' : 'No', bold: true, fontSize: cFont, alignment: 'left' }

            );

            bodyItem.push(CheckListArray);
        });

        if (bodyItem.length === 1)
            return null;

        var ChecklistTable = {
            style: 'tableExample1',
            table: {
                widths: [350, '*'],
                body: bodyItem
            }
            //layout: 'noBorders'
        };
        return ChecklistTable;
    }

    function getSurgeryCommanStructure(header, localArray) {
        var cBold = true;
        var cFont = 9;
        var hFont = 10;
        var headingFlag = 0;
        var sitem = "";
        if (localArray === undefined || localArray === "")
            return;
        var invItem1 = [];
        var bodyItem = [];
        var invItem2 = [];

        invItem2.push({ text: header, bold: true, fontSize: hFont });
        invItem2.push({ text: ':', bold: true, fontSize: hFont });
        invItem2.push({ text: localArray, fontSize: cFont });
        bodyItem.push(invItem2);

        var patientLabTestTable = {
            style: 'tableExample1',
            table: {
                widths: [170, 5, 300],
                heights: 1,
                body: bodyItem
            },
            layout: 'noBorders'
        };
        return patientLabTestTable;
    }

