    function FormArrayChecklist(data, type, header) {
        var cFont = 9;
        var hFont = 10;
        var arrayitem1 = {
            type: 'none',
            ul: []
        };

        //var arrayitem = {
        //    columns: [
        //    ]
        //}
        if (type === 'CheckBox') {
            angular.forEach(data.array, function (item) {
                var objecttable = {
                    style: 'tableExample2',
                    table: {
                        widths: [80, 30],
                        body: [
                            [{ text: item.Desc, bold: false, fontSize: cFont, alignment: 'left' }, { text: item.IsActive ? 'Yes' : 'No', bold: true, fontSize: cFont, alignment: 'left' }]

                        ]
                    },
                    layout: 'noBorders'
                };
                arrayitem1.ul.push(objecttable);
            });
        } else {
            var array1 = $filter("filter")(data.array, { "Id": data.Value }, true);

            angular.forEach(array1, function (item) {
                var objecttable = {
                    style: 'tableExample2',
                    table: {
                        //widths: [80, 30],
                        //body: [
                        //    [{ text: item.Desc, bold: true, fontSize: cFont, alignment: 'left' }, { text: item.IsActive, bold: true, fontSize: cFont, alignment: 'left' }],

                        //]
                        body: [
                            [{ text: item.Desc, bold: true, fontSize: cFont, alignment: 'left' }]

                        ]
                    },
                    layout: 'noBorders'
                };
                arrayitem1.ul.push(objecttable);
            });
        }




        //arrayitem1.ul.push(arrayitem);

        var obj = {
            ul: [
                { text: header ? header : data.Desc, bold: false, fontSize: cFont, alignment: 'left' },
                arrayitem1
            ]

        };
        return obj;
    }



