    function getSurgeryAppointmentData(localArray) {
        var cBold = true;
        var cFont = defaultFontSize;
        localArray = localArray || [];
        if (localArray.length === 0) {
            return;
        }

        var cFont = 9;
        var hFont = 10;
        var bodyItem = [];
        var bodyItem = [
            //[{ text: "Date", bold: true, fontSize: cFont },
            //{ text: 'Doctor Name', bold: true,  fontSize: cFont },
            //{ text: 'Surgery', bold: true, fontSize: cFont },
            //{ text: 'Eye', bold: true,fontSize: cFont }
            //]
            [{ text: "SNo", bold: true, fontSize: cFont },
            { text: "MR NO", bold: true, fontSize: cFont },
            { text: "Patient name", bold: true, fontSize: cFont },
            { text: "Age", bold: true, fontSize: cFont },
            { text: "Sex", bold: true, fontSize: cFont },
            { text: 'Eye', bold: true, fontSize: cFont },
            { text: 'Procedure', bold: true, fontSize: cFont },
            { text: 'Package', bold: true, fontSize: cFont },
            { text: 'IOL Power', bold: true, fontSize: cFont },
            { text: 'Surgeon', bold: true, fontSize: cFont },
            { text: 'Time', bold: true, fontSize: cFont },
            { text: 'Contact No', bold: true, fontSize: cFont },
            { text: 'Referral', bold: true, fontSize: cFont }

            ]
        ];


        angular.forEach(localArray, function (item) {
            var CheckListArray = [];
            var printage = "";
            if (item.Patient.AgeInYears !== 0) {
                printage = item.Patient.AgeInYears + 'Y ' + item.Patient.AgeInMonths + 'M';
            }
            else {
                printage = item.Patient.AgeInMonths + 'M ' + item.Patient.AgeInDays + 'D';
            }
            //CheckListArray.push(

            //    { text: $filter('date')(new Date(item.AppointmentDate), "dd-MMM-yyyy"), bold: false, fontSize: cFont, alignment: 'left' },
            //    { text: item.SurgeonName, bold: false, fontSize: cFont, alignment: 'left' },
            //    { text: item.SurgeryName, bold: false, fontSize: cFont, alignment: 'left' },
            //     { text: item.OrganId === 1 ? 'Right Eye' : (item.OrganId === 2 ? 'Left Eye' : (item.OrganId === 3 ? 'Both Eyes' : '-')), bold: false, fontSize: cFont, alignment: 'left' }
            //);
            CheckListArray.push(

                { text: item.SNO, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.Patient.PatientDisplayId, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.Patient.PatientName, bold: false, fontSize: cFont, alignment: 'left' },
                { text: printage, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.Patient.Gender, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.OrganId === 1 ? 'Right' : (item.OrganId === 2 ? 'Left' : (item.OrganId === 3 ? 'Both' : 'General')), bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.SurgeryName, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.SurgeryBillingName, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.IolPower, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.SurgeonName, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.StartTime, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.Patient.MobileNo, bold: false, fontSize: cFont, alignment: 'left' },
                { text: item.Patient.ReferalSource, bold: false, fontSize: cFont, alignment: 'left' }

            );

            bodyItem.push(CheckListArray);
        });

        if (bodyItem.length === 1) {
            return null;
        }


        var ChecklistTable = {
            style: 'tableExample',
            table: {
                widths: [20, 55, 70, 35, 20, 32, '*', 95, 40, 40, 38, 56, 50],
                body: bodyItem
            }
        };
        return ChecklistTable;
    }


