    function getNewPreOperativePrescriptions(localArray, PrintLanguageId) {
        PrintLanguageId = PrintLanguageId || 1;
        var cBold = true;
        var cFont = defaultFontSize;
        localArray = localArray || [];
        if (localArray.length === 0) {
            return;
        }
        var cFont = 9;
        var hFont = 10;
        var bodyItem = [];

        var PrescriptionHeadingArray = [];
        PrescriptionHeadingArray.push({ text: 'Medicine'.toUpperCase(), alignment: 'left', bold: true, fontSize: hFont, fillColor: '#d3d3d8', margin: [5, 2, 0, 2] },
            { text: 'Time'.toUpperCase(), alignment: 'left', bold: true, fontSize: hFont, fillColor: '#d3d3d8', margin: [0, 2, 0, 2] },
            { text: 'Dosage'.toUpperCase(), alignment: 'left', bold: true, fontSize: hFont, fillColor: '#d3d3d8', margin: [0, 2, 0, 2] },
            { text: 'Signature'.toUpperCase(), alignment: 'left', bold: true, fontSize: hFont, fillColor: '#d3d3d8', margin: [0, 2, 5, 2] }
        );
        bodyItem.push(PrescriptionHeadingArray);
        angular.forEach(localArray, function (item) {
            var precriptionsArray = [];
            var prescriptionNotesArray = [];
            //var instruction = '';
            //var durationTypeName = '';
            //if (item.DurationTypeName) {
            //    durationTypeName = item.DurationTypeName;
            //} else if (item.DurationType) {
            //    durationTypeName = item.DurationType === 'D' ? 'days' : item.DurationType === 'W' ? 'weeks' : (item.DurationType === 'M' ? 'months' : (item.DurationType === 'Y' ? 'years' : (item.DurationType === 'L' ? 'Life Time' : '')));
            //}
            //}
            var organName = "";
            item.OrganId = item.OrganId.toString();
            if (item.OrganId === '1') {
                organName = '( Right Eye )';
            }
            else if (item.OrganId === '2') {
                organName = '( Left Eye )';
            }
            else if (item.OrganId === '3') {
                organName = '( Both Eyes )';
            }
            else {
                organName = '';
            }


            //var duration = item.Duration ? item.Duration + ' ' + durationTypeName : ' ';



            precriptionsArray.push({
                text: [{ text: item.MedicineName + organName + ' ', color: 'black', bold: true, fontSize: hFont }
                ]
            },
                { text: item.MedicineUsageTimings, bold: true, fontSize: hFont },
                {
                    text: [{ text: item.Dosage, color: 'black', bold: true, fontSize: hFont }]
                },
                { text: item.AddedByName, alignment: 'left', bold: true, fontSize: hFont }
            );

            bodyItem.push(precriptionsArray);
        });

        if (bodyItem.length === 1) {
            return null;
        }


        var prescriptionTable = {
            style: 'tableExample1',
            table: {
                widths: [140, '*', 80, '*'],
                body: bodyItem
            },
            layout: 'noBorders'
        };
        return prescriptionTable;
    }
