    function getOpticalGlassPatientInfoTable(obj, marginRight) {
        var cBold = false;
        var cFont = defaultFontSize;
        if (contentSetting.patientLabTest) {
            cBold = contentSetting.patientLabTest.isBold === "Y";
            cFont = contentSetting.patientLabTest.fontSize;
        }
        var hFont = 10;
        var cFont = 9;
        var PatientName = "";
        if (obj.fullname !== '' && obj.fullname !== null && obj.fullname !== undefined) {
            PatientName = obj.fullname;
        }

        var Gender = "";
        if (obj.Sex !== '' && obj.Sex !== null && obj.Sex !== undefined) {
            Gender = obj.Sex;
        }

        var PatientID = '';

        if (obj.PatientDisplayId !== '' && obj.PatientDisplayId !== null && obj.PatientDisplayId !== undefined) {
            PatientID = obj.PatientDisplayId;
        }
        var PatientNumber = "";
        if (obj.MobileNo !== "" && obj.MobileNo !== null && obj.MobileNo !== 0) {
            PatientNumber = 'Phone : ' + '+91' + obj.MobileNo;
        }
        if (obj.AgeInYears !== 0) {
            var patientAgePrint = 'Age   :       ' + obj.AgeInYears + 'Y' + ' ' + obj.AgeInMonths + 'M';
        } else {
            patientAgePrint = 'Age   :       ' + obj.AgeInMonths + 'M' + ' ' + obj.AgeInDays + 'D';
        }
        //var patientAgePrint = "";
        //if (obj.Age !== "" && obj.Age !== null && obj.Age !== undefined) {
        //    patientAgePrint = 'Age   :       ' + obj.Age;
        //}

        var custGstNo = "";
        if (obj.GSTNo !== "" && obj.GSTNo !== null && obj.GSTNo !== undefined) {
            custGstNo = 'GST       : ' + obj.GSTNo;
        }
        var headingFlag = 0;
        var bodyItem = [];

        var patientHeadingArray = [];
        patientHeadingArray.push({ text: 'Customer Details', alignment: 'left', bold: true, fontSize: hFont, fillColor: '#d3d3d8', margin: [5, 0, 0, 0] });
        patientHeadingArray.push({ text: '', alignment: 'right', bold: true, fontSize: hFont, fillColor: '#d3d3d8', margin: [2, 0, 5, 0] });
        bodyItem.push(patientHeadingArray);

        var patientdocDetailsArray = [];
        patientdocDetailsArray.push({ text: 'Name     :  ' + PatientName, alignment: 'left', bold: false, fontSize: cFont, fillColor: '#d3d3d8', margin: [5, 0, 0, 0] });
        //patientdocDetailsArray.push({ text: PatientNumber, alignment: 'right', bold: false, fontSize: cFont, fillColor: '#d3d3d8', margin: [2, 0, 5, 0] });
        patientdocDetailsArray.push({ text: '', alignment: 'right', bold: false, fontSize: cFont, fillColor: '#d3d3d8', margin: [2, 0, 5, 0] });

        bodyItem.push(patientdocDetailsArray);
        var patientdocDetailsArray3 = [];
        patientdocDetailsArray3.push({ text: 'ID           :  ' + PatientID, alignment: 'left', bold: false, fontSize: cFont, fillColor: '#d3d3d8', margin: [5, 0, 0, 0] });
        patientdocDetailsArray3.push({ text: patientAgePrint, alignment: 'right', bold: false, fontSize: cFont, fillColor: '#d3d3d8', margin: [2, 0, 5, 0] });
        bodyItem.push(patientdocDetailsArray3);

        var patientdocDetailsArray4 = [];
        patientdocDetailsArray4.push({ text: custGstNo, alignment: 'left', bold: false, fontSize: cFont, fillColor: '#d3d3d8', margin: [5, 0, 0, 0] });
        patientdocDetailsArray4.push({ text: '', alignment: 'right', bold: false, fontSize: cFont, fillColor: '#d3d3d8', margin: [2, 0, 5, 0] });
        bodyItem.push(patientdocDetailsArray4);

        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                widths: [200, '*'],
                body: bodyItem
            },
            layout: 'noBorders'
        };
        return patientLabTestTable;
    }

    function getOpticalGlassLensTable(obj, type) {
        var cBold = false;
        var cFont = defaultFontSize;
        if (contentSetting.patientLabTest) {
            cBold = contentSetting.patientLabTest.isBold === "Y";
            cFont = contentSetting.patientLabTest.fontSize;
        }
        var hFont = 10;
        var cFont = 9;
        var headingFlag = 0;
        var bodyItem = [];
        var sitem = "";
        var citem = "";
        var invItem1 = [];
        var invItem2 = [];

        angular.forEach(obj.LensType, function (itm) {
            if (itm.IsActive === true) {
                invItem1.push(itm.Name);
                sitem = invItem1.join(", ");
            }
        });

        angular.forEach(obj.LensCoating, function (itm) {
            if (itm.IsActive === true) {
                invItem2.push(itm.Name);
                citem = invItem2.join(", ");
            }
        });

        var ltype = "";
        var ctype = "";
        if (type === 'New') {
            ltype = 'Glass LensType : ';
            ctype = 'Glass LensCoating : ';
        }
        var patientdocDetailsArray2 = [];
        if (sitem !== "") {
            patientdocDetailsArray2.push({
                text: [{ text: ltype, fontSize: cFont, bold: true }, { text: ' ' + sitem, fontSize: cFont, bold: false }], margin: [5, 0, 2, 0], alignment: 'left', fontSize: cFont
            });
        }

        if (citem !== "") {
            patientdocDetailsArray2.push({
                text: [{ text: ctype, fontSize: cFont, bold: true }, { text: ' ' + citem, fontSize: cFont, bold: false }], margin: [0, 0, 0, 0], alignment: 'right', fontSize: cFont
            });
        }

        if (sitem !== "" || citem !== "") {
            bodyItem.push(patientdocDetailsArray2);
        }
        if (bodyItem.length === 0) {
            return null;
        }


        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                widths: [300, '*'],
                heights: 5,
                body: bodyItem
            },
            layout: 'noBorders'
        };
        return patientLabTestTable;
    }




