    function getInvPurchaseDetailsArrayTable2(OrderDetailsArray, margin) {

        var bodyItem = [];

        var colorHeader = '#e8e8e8';
        var cFont = 9;
        var hFont = 10;

        var bodyItem = [
            [
                {
                    text: 'Product',
                    bold: true,
                    fillColor: colorHeader,
                    fontSize: hFont
                },
                {
                    text: 'Strips',
                    bold: true,
                    fillColor: colorHeader,
                    fontSize: hFont
                },
                {
                    text: 'Qty',
                    bold: true,
                    fillColor: colorHeader,
                    fontSize: hFont
                },
                {
                    text: 'T.Qty',
                    bold: true,
                    fillColor: colorHeader,
                    fontSize: hFont
                },
                {
                    text: 'Price',
                    bold: true,
                    fillColor: colorHeader,
                    fontSize: hFont,
                    margin: [5, 0, 0, 0]
                },
                {
                    text: 'GST',
                    bold: true,
                    fillColor: colorHeader,
                    fontSize: hFont
                },
                {
                    text: 'Amount',
                    bold: true,
                    fillColor: colorHeader,
                    fontSize: hFont
                }
            ]
        ];

        angular.forEach(OrderDetailsArray, function (subitem) {
            var totalAmount = "";
            var Qty = "";
            var noitems = "";
            var nounits = "";
            var freestrips = "";
            if (subitem.NoOfItems !== undefined) {
                noitems = subitem.NoOfItems;
            }

            if (subitem.NoOfUnits !== undefined) {
                nounits = subitem.NoOfUnits;
            }
            if (subitem.FreeStrips !== undefined) {
                freestrips = subitem.FreeStrips;
            }
            Qty = noitems * nounits;

            var strips = "";
            strips = nounits + freestrips;

            var actualprice = "";
            actualprice = (subitem.ActualCost) / (subitem.NoOfItems);

            var Expiry = "";
            var emonth = "";
            var eyear = "";
            if (subitem.ExpiryDateMonth !== undefined) {
                emonth = subitem.ExpiryDateMonth;
            }
            if (subitem.ExpiryDateYear !== undefined) {
                eyear = subitem.ExpiryDateYear;
            }
            if (emonth !== null && eyear !== null) {
                Expiry = emonth + '/ ' + eyear;
            } else {
                Expiry = '';
            }


            totalAmount = Qty * actualprice;

            var invarray1 = [];



            if (subitem.CategoryId === 6) {//for lens

                subitem.ModelName = subitem.ModelName === "" ? "--" : subitem.ModelName;
                subitem.LensTypeName = subitem.LensTypeName === "" ? "--" : subitem.LensTypeName;
                subitem.CoatingName = subitem.CoatingName === "" ? "--" : subitem.CoatingName;
                subitem.IndexName = subitem.IndexName === "" ? "--" : subitem.IndexName;
                subitem.PowerName = subitem.PowerName === "" ? "--" : subitem.PowerName;
                subitem.SizeName = subitem.SizeName === "" ? "--" : subitem.SizeName;
                subitem.ColourName = subitem.ColourName === "" ? "--" : subitem.ColourName;


                subitem.ItemName = subitem.ItemName + "\n" + "Model:" + subitem.ModelName + ", " + "Type:" + subitem.LensTypeName + ", " + "Coating:" + subitem.CoatingName + ", " + "Index:" + subitem.IndexName + "\n" + "Power:" + subitem.PowerName + ", " + "Size:" + subitem.SizeName + ", " + "Colour:" + subitem.ColourName;
            }




            if (subitem.CategoryId === 7) {//for iol

                subitem.IolAcPc = subitem.IolAcPc === "" ? "--" : subitem.IolAcPc;
                subitem.IolType = subitem.IolType === "" ? "--" : subitem.IolType;
                subitem.IolModel = subitem.IolModel === "" ? "--" : subitem.IolModel;
                subitem.IolOptic = subitem.IolOptic === "" ? "--" : subitem.IolOptic;
                subitem.IolPower = subitem.IolPower === "" ? "--" : subitem.IolPower;
                subitem.IolLength = subitem.IolLength === "" ? "--" : subitem.IolLength;
                subitem.IolAConst = subitem.IolAConst === "" ? "--" : subitem.IolAConst;


                subitem.ItemName = subitem.ItemName + "\n" + "Ac/Pc:" + subitem.IolAcPc + ", " + "Type:" + subitem.IolType + ", " + "Model:" + subitem.IolModel + ", " + "Optic:" + subitem.IolOptic + "\n" + "Power:" + subitem.IolPower + ", " + "Length:" + subitem.IolLength + ", " + "A-Constant:" + subitem.IolAConst;
            }



            invarray1.push({ text: subitem.ItemName, fontSize: cFont });
            invarray1.push({ text: noitems, fontSize: cFont });
            invarray1.push({ text: nounits, fontSize: cFont });
            invarray1.push({ text: Qty, fontSize: cFont });
            invarray1.push({ text: actualprice.toFixed(2), fontSize: cFont });
            invarray1.push({ text: subitem.GST, fontSize: cFont });
            invarray1.push({ text: totalAmount.toFixed(2), fontSize: cFont });
            bodyItem.push(invarray1);
        });


        var patientBillingTable = {
            style: 'tableExample',
            table: {
                widths: [260, 30, 30, 40, 40, 30, '*'],
                body: bodyItem
            },
            layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return (i === 0 || i === node.table.widths.length) ? 'gray' : 'gray';
                }
            }

        };
        return patientBillingTable;
    }
