    this.newInvestigationForPrint = function (scopeObj) {
        var printSettingInfo = eHnoteMasterDataService.getPrintSettingSpecific("Billing").PageSettings;
        var emptyRow = getEmptyTable();
        doctorinfo = scopeObj.doctorinfo;
        var data = printSettings;
        var pageSettings = {
            "marginLeft": 40,
            "marginTop": 100,
            "marginRight": 40,
            "marginBottom": 10
        };
        var headerHeight = 100;
        var footerHeight = 100;
        var docSign = "";
        var isDefaultDocSign = "";
        printPageSize = "A4";
        contentSetting = setContentSettings();
        if (data !== undefined) {
            pageSettings = data.JsonSetting.pageSettings;
            headerHeight = data.JsonSetting.clinicSettings.headerSettings.dimension.height;
            footerHeight = data.JsonSetting.clinicSettings.footerSettings.dimension.height;
            contentSetting = data.JsonSetting.clinicSettings.contentSettings;
            docSign = data.JsonSetting.clinicSettings.footerSettings.custFootSign;
            isDefaultDocSign = data.JsonSetting.clinicSettings.footerSettings.isFootSignDefault;
            if (printSettingInfo.PageSize === "A4") {
                defaultFontSize = 10;
            } else {
                printPageSize = "A5";
                defaultFontSize = 8;
            }
        }
        var content = [];
        var cFont = 7;
        var cBold = true;

        var IsHeaderLogoAvail = eHnoteMasterDataService.getPrintSettingSpecific("Billing").LetterHeadValue;
        if (IsHeaderLogoAvail === "No") {



            var branchName = "";


            branchName = scopeObj.appointmentinfo.BranchName || "";



            var doctorName = "";
            doctorName = scopeObj.appointmentinfo.DoctorFullName || "";
            doctorName = scopeObj.appointmentinfo.DoctorName || "";



            var HospitalName = branchName;

            var headerPrint = getNewPrintHeaderSettings(scopeObj.appointmentinfo, doctorinfo, printSettingInfo.MarginRight, printSettingInfo.PageOrientation) || null;

            if (headerPrint !== null) {
                content.push(headerPrint);
            }
        }




        var patientinfodetails = getNewPatientInfoTableForinvBilling(scopeObj.PatientDetails) || null;

        if (patientinfodetails !== null) {
            content.push(patientinfodetails);
        }

        var patientinvestigation = getNewPatientInvestigation(scopeObj.Investigationarray) || null;
        if (patientinvestigation !== null) {
            content.push(patientinvestigation);
        }
        var Signature = getOpticalSignatureInfo(scopeObj.Signature) || null;

        if (Signature !== null) {
            content.push(Signature);
        }

        content.push(getFootNote());
        var docdefination = {
            content: content,
            defaultStyle: {
                font: "Roboto"
            },
            header: function (currentPage, pageCount) {
                var headerSetting = getHeader(data, printSettingInfo.MarginRight, printSettingInfo.PageOrientation);
                headerSetting.margin = [printSettingInfo.MarginLeft, printSettingInfo.MarginTop, printSettingInfo.MarginRight, 20];
                return headerSetting;
            },
            footer: function (currentPage, pageCount) {
                var footerSetting = getFooter(data, printSettingInfo.MarginRight, printSettingInfo.PageOrientation);
                footerSetting.margin = [printSettingInfo.MarginLeft, 5, printSettingInfo.MarginRight, printSettingInfo.MarginBottom];
                return footerSetting;
            },
            pageMargins: [printSettingInfo.MarginLeft, headerHeight + printSettingInfo.MarginTop, printSettingInfo.MarginRight, footerHeight + printSettingInfo.MarginBottom],
            pageSize: printSettingInfo.PageSize,
            pageOrientation: printSettingInfo.PageOrientation,
            styles: {
                header: {
                    fontSize: 18,
                    bold: true,
                    margin: [20, 20, 20, 30]
                },
                titleHeader: {
                    fontSize: 18,
                    bold: true,
                    alignment: "left",
                    margin: [40, 10, 10, 20],
                    paddingBottom: 200
                },
                footer: {
                    alignment: "right",
                    margin: [20, 10, 40, 20]
                },
                subheader: {
                    fontSize: 16,
                    bold: true,
                    margin: [0, 10, 0, 5]
                },
                tableExample: {
                    margin: [0, 5, 0, 15]
                },
                tableHeader: {
                    bold: true,
                    fontSize: 10,
                    color: "black"
                },
                contentText: {
                    fontSize: 10
                }
            }
        };
        pdfMake.fonts = {
            Roboto: {
                normal: 'Roboto-Regular.ttf',
                bold: 'Roboto-Medium.ttf',
                italics: 'Roboto-Italic.ttf',
                bolditalics: 'Roboto-MediumItalic.ttf'
            },
            Kannada: {
                normal: 'NotoSansKannada-Regular.ttf',
                bold: 'NotoSansKannada-Regular.ttf',
                italics: 'NotoSansKannada-Regular.ttf',
                bolditalics: 'NotoSansKannada-Regular.ttf'
            },
            marati: {
                normal: 'lohiMarathi-Regular.ttf',
                bold: 'lohiMarathi-Regular.ttf',
                italics: 'lohiMarathi-Regular.ttf',
                bolditalics: 'lohiMarathi-Regular.ttf'
            },
            telugu: {
                normal: 'NotoSanstelugu-Regular.ttf',
                bold: 'NotoSanstelugu-Regular.ttf',
                italics: 'NotoSanstelugu-Regular.ttf',
                bolditalics: 'NotoSanstelugu-Regular.ttf'
            },
            hindhi: {
                normal: 'NotoSanshindhi-regular.ttf',
                bold: 'NotoSanshindhi-regular.ttf',
                italics: 'NotoSanshindhi-regular.ttf',
                bolditalics: 'NotoSanshindhi-regular.ttf'
            },
            Panjab: {
                normal: 'lohithPanjabi-regular.ttf',
                bold: 'lohithPanjabi-regular.ttf',
                italics: 'lohithPanjabi-regular.ttf',
                bolditalics: 'lohithPanjabi-regular.ttf'
            }

        };

        pdfMake.createPdf(docdefination).print();
    };
    



   
