        doctorNameSubArray2.push({ text: ' : ', bold: false, fontSize: cfont, fillColor: '#d3d3d8' });
        doctorNameSubArray2.push({ text: AppDate, bold: false, fontSize: cfont, fillColor: '#d3d3d8' });

