    this.GenerateAddPatientDepositPrint = function (scopeObj) {
        var doctorinfo = eHnoteMasterDataService.getUserInfo();
        var appointmentinfo = eHnoteMasterDataService.getAppointmentInfo();
        var printSettingInfo = eHnoteMasterDataService.getPrintSettingSpecific("Billing").PageSettings;
        var emptyRow = getEmptyTable();

        var data = printSettings;
        var pageSettings = {
            "marginLeft": 40,
            "marginTop": 100,
            "marginRight": 40,
            "marginBottom": 10
        };
        var headerHeight = 100;
        var footerHeight = 100;
        var docSign = "";
        var isDefaultDocSign = "";
        printPageSize = "A4";
        contentSetting = setContentSettings();
        if (data !== undefined) {
            pageSettings = data.JsonSetting.pageSettings;
            headerHeight = data.JsonSetting.clinicSettings.headerSettings.dimension.height;
            footerHeight = data.JsonSetting.clinicSettings.footerSettings.dimension.height;
            contentSetting = data.JsonSetting.clinicSettings.contentSettings;
            docSign = data.JsonSetting.clinicSettings.footerSettings.custFootSign;
            isDefaultDocSign = data.JsonSetting.clinicSettings.footerSettings.isFootSignDefault;
            if (printSettingInfo.PageSize === "A4") {
                defaultFontSize = 10;
            } else {
                printPageSize = "A5";
                defaultFontSize = 8;
            }
        }
        var content = [];
        var cFont = 7;
        var cBold = true;

        var IsHeaderLogoAvail = eHnoteMasterDataService.getPrintSettingSpecific('Billing').LetterHeadValue;
        if (IsHeaderLogoAvail === 'No') {

            var headerPrint = NewGetBillingPrintHeaderSettings('', doctorinfo, '', printSettingInfo.MarginRight, printSettingInfo.PageOrientation) || null;

            if (headerPrint !== null) {
                content.push(headerPrint);
            }
            printSettingInfo.MarginTop = 25;
        }

        if (IsHeaderLogoAvail === "Image") {


            var headerPrint = getNewPrintImageHeaderForBilling() || null;

            if (headerPrint !== null) {
                content.push(headerPrint);
            }
        }

        content.push({
            columns: [
                {
                    text: scopeObj.BillingType.toUpperCase(), color: "black", bold: true, fontSize: 12, alignment: "center"
                }
            ]
        });


        var patientinfodetails = getNewDepositPatientInfoTableForBilling(scopeObj, scopeObj.DepositeDetails, ) || null;


        if (patientinfodetails !== null) {
            content.push(patientinfodetails);
        }

        var ReceiptNo = "";
        if (scopeObj.DepositeDetails.ReceiptNo != "" && scopeObj.DepositeDetails.ReceiptNo != undefined) {
            ReceiptNo = scopeObj.DepositeDetails.ReceiptNo;
        }

        content.push({
            columns: [
                { text: "Receipt No :" + checkUndefinedVal(ReceiptNo), color: "black", fontSize: 10,  alignment: "left"},
                //{
                //    text: scopeObj.BillingType.toUpperCase(), color: "black", bold: true, fontSize: 12, alignment: "center"
                //},
                {
                    text: "Printed Date :" + scopeObj.PrintedDatenTime, color: "black", fontSize: 10, alignment: "right"
                }
            ]
        });

        content.push({
            columns: [
                {
                    text: "Printed By :" + scopeObj.DepositeDetails.CreatedBy, color: "black", fontSize: 10, alignment: "right"
                }
            ]
        });

        var BillingDetailsArray = getBillingAdvanceDetailsArrayTable(scopeObj) || null;

        if (BillingDetailsArray !== null) {
            content.push(BillingDetailsArray);
        }

        content.push({ text: "Total Amount :" + " $" +' '+ scopeObj.DepositeDetails.DepositAmount + " " , color: "black", fontSize: 10, alignment: "right"});


        //if (scopeObj.doctorinfo !== undefined || scopeObj.appointmentinfo !== undefined) {
        //    content.push(getBillingDoctorSignatureInfo(scopeObj.doctorinfo, scopeObj.appointmentinfo, scopeObj.BillingObject));
        //}
        content.push({
            text: ' '
        });

        content.push(getFootNote());
        if (IsHeaderLogoAvail === "Image") {
            var docdefination = {
                content: content,
                defaultStyle: {
                    font: "Roboto"
                },
                header: function (currentPage, pageCount) {
                    var headerSetting = getHeader(data, printSettingInfo.MarginRight, printSettingInfo.PageOrientation);
                    headerSetting.margin = [printSettingInfo.MarginLeft, printSettingInfo.MarginTop, printSettingInfo.MarginRight, 20];
                    return headerSetting;
                },
                footer: function (currentPage, pageCount) {
                    if (currentPage === 1) {
                        var footerSetting = getImageFooter(data, printSettingInfo.MarginRight, printSettingInfo.PageOrientation);
                        return footerSetting;
                    } else {
                        var footerSetting = getFooter(data, printSettingInfo.MarginRight, printSettingInfo.PageOrientation);
                        footerSetting.margin = [printSettingInfo.MarginLeft, 5, printSettingInfo.MarginRight, printSettingInfo.MarginBottom];
                        return footerSetting;
                    }

                },
                pageMargins: [printSettingInfo.MarginLeft, 0, printSettingInfo.MarginRight, 60],
                pageSize: printSettingInfo.PageSize,
                pageOrientation: printSettingInfo.PageOrientation,
                styles: {
                    header: {
                        fontSize: 18,
                        bold: true,
                        margin: [20, 20, 20, 30]
                    },
                    titleHeader: {
                        fontSize: 18,
                        bold: true,
                        alignment: "left",
                        margin: [40, 10, 10, 20],
                        paddingBottom: 200
                    },
                    footer: {
                        alignment: "right",
                        margin: [20, 10, 40, 0]
                    },
                    subheader: {
                        fontSize: 16,
                        bold: true,
                        margin: [0, 10, 0, 5]
                    },
                    tableExample: {
                        margin: [0, 5, 0, 15]
                    },
                    tableHeader: {
                        bold: true,
                        fontSize: 10,
                        color: "black"
                    },
                    contentText: {
                        fontSize: 10
                    }
                }
            };
        } else {
            var docdefination = {
                content: content,
                defaultStyle: {
                    font: 'Roboto'
                },
                header: function (currentPage, pageCount) {
                    var headerSetting = getHeader(data, printSettingInfo.MarginRight, printSettingInfo.PageOrientation);
                    headerSetting.margin = [printSettingInfo.MarginLeft, printSettingInfo.MarginTop, printSettingInfo.MarginRight, 20];
                    return headerSetting;
                },
                footer: function (currentPage, pageCount) {
                    var footerSetting = getFooter(data, printSettingInfo.MarginRight, printSettingInfo.PageOrientation);
                    footerSetting.margin = [printSettingInfo.MarginLeft, 5, printSettingInfo.MarginRight, printSettingInfo.MarginBottom];
                    return footerSetting;
                },
                pageMargins: [printSettingInfo.MarginLeft, headerHeight + printSettingInfo.MarginTop, printSettingInfo.MarginRight, footerHeight + printSettingInfo.MarginBottom],
                pageSize: printSettingInfo.PageSize,
                pageOrientation: printSettingInfo.PageOrientation,
                styles: {
                    header: {
                        fontSize: 18,
                        bold: true,
                        margin: [20, 20, 20, 30]
                    },
                    titleHeader: {
                        fontSize: 18,
                        bold: true,
                        alignment: 'left',
                        margin: [40, 10, 10, 20],
                        paddingBottom: 200
                    },
                    footer: {
                        alignment: 'right',
                        margin: [20, 10, 40, 20]
                    },
                    subheader: {
                        fontSize: 16,
                        bold: true,
                        margin: [0, 10, 0, 5]
                    },
                    tableExample: {
                        margin: [0, 5, 0, 15]
                    },
                    tableHeader: {
                        bold: true,
                        fontSize: 10,
                        color: 'black'
                    },
                    contentText: {
                        fontSize: 10
                    }
                }
            };


        }


        pdfMake.createPdf(docdefination).print();
    };

